package com.mod.htgt6.minecraft1202.Module.Items.Bountiful;
import java.util.List;import net.minecraft.creativetab.CreativeTabs;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.item.EnumAction;import net.minecraft.item.Item;import net.minecraft.item.ItemStack;import net.minecraft.potion.Potion;import net.minecraft.potion.PotionEffect;import net.minecraft.world.World;
/** Drinkable 1.8 Potion of Leaping in normal, extended and strong forms. */
public final class ItemBountifulLeapingPotion extends Item {public ItemBountifulLeapingPotion(){setUnlocalizedName("bountiful_leaping_potion");setTextureName("minecraft:potion_bottle_drinkable");setHasSubtypes(true);setMaxDamage(0);setMaxStackSize(1);setCreativeTab(null);}@Override public int getMaxItemUseDuration(ItemStack stack){return 32;}@Override public EnumAction getItemUseAction(ItemStack stack){return EnumAction.drink;}@Override public ItemStack onItemRightClick(ItemStack stack,World world,EntityPlayer player){player.setItemInUse(stack,getMaxItemUseDuration(stack));return stack;}@Override public ItemStack onEaten(ItemStack stack,World world,EntityPlayer player){if(!player.capabilities.isCreativeMode)--stack.stackSize;if(!world.isRemote){int meta=Math.min(2,stack.getItemDamage());int duration=meta==1?9600:meta==2?1800:3600;player.addPotionEffect(new PotionEffect(Potion.jump.id,duration,meta==2?1:0));}return stack.stackSize<=0?new ItemStack(net.minecraft.init.Items.glass_bottle):stack;}@Override public String getUnlocalizedName(ItemStack stack){return super.getUnlocalizedName()+"."+Math.min(2,stack.getItemDamage());}@Override @SuppressWarnings({"rawtypes","unchecked"})public void getSubItems(Item item,CreativeTabs tab,List list){}}
